    """
    Matches a .gitignore pattern against a path.

    Rules:
    - Pattern with no slash (other than trailing) matches at any depth.
    - Pattern containing a slash (not at end) is anchored at root.
    - Leading slash anchors at root.
    - Trailing slash means pattern only matches a directory (path ends with '/').
    - '*' never matches a slash.
    - '?' matches one non-slash character.
    - '**/' matches zero or more leading directories.
    - '/**' at the end matches everything inside.
    - '[abc]' is a character class.
    """

    # Normalize inputs: ensure path does not start with '/' as per spec
    if path.startswith('/'):
        path = path[1:]

    # Handle trailing slash in pattern to indicate directory match
    is_dir_pattern = pattern.endswith('/')
    if is_dir_pattern:
        pattern = pattern[:-1]
        # Path must also be treated as a directory
        if not path.endswith('/'):
            return False

    # If pattern starts with '/', it's anchored to root
    if pattern.startswith('/'):
        pattern = pattern[1:]
        # Must match from the beginning of the path
        if not _match_single_level(pattern, path):
            return False
    else:
        # Pattern without leading slash can match at any level
        # But if it contains a slash (and isn't just '**/'), it's anchored
        if '/' in pattern and not pattern.endswith('**/'):
            # Anchored at root
            if not _match_single_level(pattern, path):
                return False
        else:
            # Can match anywhere
            parts = path.split('/')
            for i in range(len(parts)):
                sub_path = '/'.join(parts[i:])
                if _match_single_level(pattern, sub_path):
                    return True
            return False

    # If we reach here, the pattern was anchored (either by leading / or internal /)
    # and we've already checked the single-level match above.
    # However, we need to handle the case where the initial check passed but 
    # we need to verify the logic flow. The function structure above handles most cases.

    # Special handling for patterns that might have been simplified incorrectly
    # Re-evaluate based on the specific rules for complex patterns like **/

    # Let's refactor to be more robust according to gitignore semantics

    def normalize_and_check(p, p_path):
        # Remove leading slash if present for anchoring logic
        anchored = p.startswith('/')
        if anchored:
            p = p[1:]

        # Check for trailing slash indicating directory
        dir_only = p.endswith('/')
        if dir_only:
            p = p[:-1]
            if not p_path.endswith('/'):
                return False

        # Handle **/ prefix
        if p.startswith('**/'):
            suffix = p[3:]
            # **/ matches zero or more directories
            # We need to find a split point where the suffix matches the rest
            parts = p_path.split('/')
            for i in range(len(parts) + 1):
                remaining = '/'.join(parts[i:])
                if _fnmatch_suffix(suffix, remaining):
                    return True
            return False

        # Handle /** at the end
        if p.endswith('/**'):
            prefix = p[:-3]
            # This matches everything inside the prefix directory
            # So we just need to see if the path starts with the prefix
            if prefix == '':
                # /** matches everything under root
                return True
            # Check if path starts with prefix/
            if p_path.startswith(prefix + '/'):
                return True
            return False

        # Standard fnmatch for non-anchored or simple anchored patterns
        if anchored:
            return _fnmatch_exact(p, p_path)
        else:
            # Try matching at each level
            parts = p_path.split('/')
            for i in range(len(parts)):
                sub = '/'.join(parts[i:])
                if _fnmatch_exact(p, sub):
                    return True
            return False

    def _fnmatch_exact(pat, text):
        # Custom fnmatch that doesn't allow * to match /
        # Convert glob pattern to regex
        # Escape special regex chars except our globs
        regex_parts = []
        i = 0
        while i < len(pat):
            c = pat[i]
            if c == '*':
                regex_parts.append('[^/]*')
            elif c == '?':
                regex_parts.append('[^/]')
            elif c == '[':
                # Find closing bracket
                j = i + 1
                if j < len(pat) and pat[j] == '!':
                    j += 1
                if j < len(pat) and pat[j] == ']':
                    j += 1
                while j < len(pat) and pat[j] != ']':
                    j += 1
                if j < len(pat):
                    regex_parts.append(re.escape(pat[i:j+1]))
                    i = j
                else:
                    regex_parts.append(re.escape(c))
            else:
                regex_parts.append(re.escape(c))
            i += 1

        regex = '^' + ''.join(regex_parts) + '$'
        return bool(re.match(regex, text))

    def _fnmatch_suffix(pat, text):
        # For patterns like "foo/**" where foo is fixed and /** is handled separately
        # Actually, this helper is for when we strip **/ and want to match the rest
        # But our main logic handles **/ specially. This might not be needed if logic is correct.
        # Let's rely on _fnmatch_exact for the suffix part after stripping **/
        return _fnmatch_exact(pat, text)

    return normalize_and_check(pattern, path)
