def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list[tuple[int, int]]: A list of (start, end) inclusive byte offsets, 
                              or None if the header is unsatisfiable or malformed.
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes=" prefix
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        start = None
        end = None

        if "-" not in part:
            # Malformed: missing dash
            continue

        if part.startswith("-"):
            # Suffix range: e.g., "-500"
            suffix_length_str = part[1:]
            if not suffix_length_str:
                # Empty suffix length is invalid per RFC 7233 unless it's just "-" which implies last byte? 
                # Actually RFC says: "If the first number is omitted, then the range extends from the last N-bytes to the last byte."
                # But we need a number. If it's just "-", it's ambiguous. Let's assume valid input has a number after '-'.
                # However, strictly speaking, "bytes=-" means the last byte only? No, usually requires a count.
                # Re-reading RFC 7233 Section 2.1: "suffix-length-byte-range-spec = "-" * 1DIGIT"
                # So "-" alone is invalid. We need at least one digit.
                return None

            try:
                suffix_length = int(suffix_length_str)
            except ValueError:
                return None

            if suffix_length <= 0:
                return None

            start = size - suffix_length
            end = size - 1

            # Clamp start to 0 if calculation goes negative (though suffix_length > size handled below)
            if start < 0:
                start = 0
                end = size - 1
            elif start >= size:
                # Suffix larger than resource -> whole resource
                start = 0
                end = size - 1
            else:
                # Check if end is past the last byte (shouldn't happen with correct math but good safety)
                if end >= size:
                    end = size - 1

        else:
            # Regular range: "start-end" or "start-"
            components = part.split("-", 1)
            if len(components) != 2:
                return None

            start_str, end_str = components

            if start_str == "":
                # Start omitted is invalid for non-suffix ranges
                return None

            try:
                start = int(start_str)
            except ValueError:
                return None

            if start < 0:
                return None

            if start >= size:
                # This specific range is unsatisfiable, skip it
                continue

            if end_str == "":
                # End omitted: runs to the end
                end = size - 1
            else:
                try:
                    end = int(end_str)
                except ValueError:
                    return None

                if end < start:
                    # Invalid range where end < start
                    continue

                # Clamp end to size - 1
                if end >= size:
                    end = size - 1

        # Add valid range
        if start is not None and end is not None and start <= end:
            ranges.append((start, end))

    if not ranges:
        return None

    return ranges
