class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.key_to_node = {}  # key -> Node
        self.freq_to_nodes = {}  # frequency -> doubly linked list of nodes with that frequency
        self.min_freq = 0

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.prev = None
            self.next = None

    def _remove_node(self, node):
        prev_node = node.prev
        next_node = node.next
        if prev_node:
            prev_node.next = next_node
        else:
            # This is the head of a list
            if self.freq_to_nodes[self.node_freq(node)] == node:
                del self.freq_to_nodes[self.node_freq(node)]
                self.min_freq = max(0, self.min_freq - 1)

        if next_node:
            next_node.prev = prev_node

    def _add_node_to_head(self, freq):
        if freq not in self.freq_to_nodes:
            self.freq_to_nodes[freq] = self.Node(-1, -1)  # Dummy head for this frequency
            self.freq_to_nodes[freq].next = self.freq_to_nodes[freq].prev = self.freq_to_nodes[freq]

        new_node = self.Node(-1, -1)  # Dummy node to insert at head
        new_node.next = self.freq_to_nodes[freq].next
        new_node.prev = self.freq_to_nodes[freq]
        self.freq_to_nodes[freq].next.prev = new_node
        self.freq_to_nodes[freq].next = new_node

    def _update_freq(self, node):
        old_freq = self.node_freq(node)
        self._remove_node(node)
        new_freq = old_freq + 1
        self._add_node_to_head(new_freq)
        node.freq = new_freq

    @staticmethod
    def node_freq(node):
        return node.freq if hasattr(node, 'freq') else 0

    def get(self, key: int) -> int:
        if key not in self.key_to_node:
            return -1

        node = self.key_to_node[key]
        self._update_freq(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        if key in self.key_to_node:
            node = self.key_to_node[key]
            node.value = value
            self._update_freq(node)
        else:
            if self.size >= self.capacity:
                # Evict least frequently used (and least recently used among them)
                lfu_list = self.freq_to_nodes.get(self.min_freq)
                if lfu_list:
                    tail = lfu_list.prev
                    self._remove_node(tail)
                    del self.key_to_node[tail.key]
                    self.size -= 1

            new_node = self.Node(key, value)
            new_node.freq = 1
            self.key_to_node[key] = new_node
            self._add_node_to_head(1)
            self.size += 1
            self.min_freq = 1

