class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.snapshots = {}

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        return root

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]

        self.history.append((root_b, root_a, self.size[root_a]))
        return True

    def snapshot(self):
        token = id(self) + len(self.history)
        self.snapshots[token] = len(self.history)
        return token

    def rollback(self, token):
        if token not in self.snapshots:
            raise ValueError("Invalid snapshot token")

        target_len = self.snapshots[token]
        while len(self.history) > target_len:
            _, new_root, old_size = self.history.pop()
            current_root = self.find(new_root)
            self.parent[current_root] = new_root
            self.size[new_root] = old_size

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)

