    def __init__(self):
        self.root = {}

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['$'] = True  # Mark end of word

    def remove(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node:
                return False
            node = node[char]

        if '$' not in node:
            return False

        del node['$']
        # Clean up empty nodes to keep the trie compact and ensure removal is complete
        self._clean(node)
        return True

    def _clean(self, node: dict) -> None:
        """Recursively remove empty dictionaries from the trie."""
        keys_to_remove = [k for k in node.keys() if k != '$' and not node[k]]
        for k in keys_to_remove:
            del node[k]
        if not node:
            return

    def search(self, pattern: str) -> list:
        results = []
        self._search_helper(self.root, pattern, 0, [], results)
        return sorted(results)

    def _search_helper(self, node: dict, pattern: str, idx: int, current_path: list, results: list) -> None:
        if idx == len(pattern):
            if '$' in node:
                results.append("".join(current_path))
            return

        char = pattern[idx]
        if char == '.':
            # '.' matches exactly one character
            for key in node:
                if key != '$':
                    current_path.append(key)
                    self._search_helper(node[key], pattern, idx + 1, current_path, results)
                    current_path.pop()
        else:
            if char in node:
                current_path.append(char)
                self._search_helper(node[char], pattern, idx + 1, current_path, results)
                current_path.pop()

