import threading

class TokenBucket:
    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = float(capacity)
        self.refill_rate = float(refill_per_sec)
        self.clock = clock
        self.tokens = float(self.capacity)
        self.last_time = self.clock()

    def _get_current_tokens(self):
        now = self.clock()
        if now < self.last_time:
            # Time should not move backwards per spec, but handle defensively
            now = self.last_time

        elapsed = now - self.last_time
        if elapsed > 0 and self.refill_rate > 0:
            refilled = elapsed * self.refill_rate
            self.tokens = min(self.capacity, self.tokens + refilled)

        self.last_time = now
        return self.tokens

    def take(self, n=1):
        if n <= 0:
            return True

        available = self._get_current_tokens()

        if available >= n:
            self.tokens -= n
            return True
        else:
            return False
