def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if len(alphabet) != len(set(alphabet)):
        raise ValueError("Alphabet must contain distinct characters")

    zero_char = alphabet[0]
    if n == 0:
        return zero_char

    negative = n < 0
    n = abs(n)
    digits = []

    while n > 0:
        n, remainder = divmod(n, len(alphabet))
        digits.append(alphabet[remainder])

    result = ''.join(reversed(digits))
    return '-' + result if negative else result


def from_base(s, alphabet):
    if not s:
        raise ValueError("String cannot be empty")

    if len(alphabet) != len(set(alphabet)):
        raise ValueError("Alphabet must contain distinct characters")

    if s.startswith('-'):
        is_negative = True
        s = s[1:]
    else:
        is_negative = False

    if not s:
        raise ValueError("String cannot be empty after sign removal")

    for char in s:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' not in alphabet")

    value = 0
    base = len(alphabet)
    for char in s:
        index = alphabet.index(char)
        value = value * base + index

    return -value if is_negative else value
