import heapq

def topo_lex(graph):
    # Collect all unique nodes from both keys and values
    all_nodes = set(graph.keys())
    for successors in graph.values():
        all_nodes.update(successors)

    if not all_nodes:
        return []

    # Calculate in-degree for each node
    in_degree = {node: 0 for node in all_nodes}

    for node, successors in graph.items():
        for successor in successors:
            in_degree[successor] += 1

    # Initialize heap with nodes that have zero in-degree
    # Use a min-heap to get the lexicographically smallest node
    ready_heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready_heap)

    result = []

    while ready_heap:
        current_node = heapq.heappop(ready_heap)
        result.append(current_node)

        # If this node has no successors in the graph dict, skip
        if current_node not in graph:
            continue

        successors = graph[current_node]
        for successor in successors:
            in_degree[successor] -= 1
            if in_degree[successor] == 0:
                heapq.heappush(ready_heap, successor)

    # Check for cycle
    if len(result) != len(all_nodes):
        return None

    return result

