    def __init__(self):
        self._values = {}  # cell -> raw value (number or formula string)
        self._deps = {}    # cell -> set of cells it depends on
        self._rev_deps = {} # cell -> set of cells that depend on it

    def _parse_formula(self, formula_str):
        """Parse a formula string into an AST-like structure for evaluation."""
        if not formula_str.startswith('='):
            raise ValueError("Formula must start with '='")

        expr = formula_str[1:]
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i] in '+-*':
                tokens.append(('OP', expr[i]))
                i += 1
            elif expr[i:i+2] == 'A' and expr[i+1].isdigit():
                # Cell reference A1, B2, etc.
                j = i + 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(('REF', expr[i:j]))
                i = j
            elif expr[i].isdigit() or (expr[i] == '-' and i > 0 and expr[i-1] not in '+*-'):
                # Integer literal
                j = i
                if expr[i] == '-':
                    j += 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(('NUM', int(expr[i:j])))
                i = j
            else:
                raise ValueError(f"Invalid character in formula at position {i}: {expr[i]}")

        return self._build_tree(tokens)

    def _build_tree(self, tokens):
        """Build expression tree from tokens using recursive descent."""
        pos = [0]

        class Parser:
            def parse_expr(self):
                left = self.parse_term()
                while pos[0] < len(tokens) and tokens[pos[0]][0] == 'OP' and tokens[pos[0]][1] in '+-':
                    op = tokens[pos[0]][1]
                    pos[0] += 1
                    right = self.parse_term()
                    left = ('BINOP', op, left, right)
                return left

            def parse_term(self):
                left = self.parse_factor()
                while pos[0] < len(tokens) and tokens[pos[0]][0] == 'OP' and tokens[pos[0]][1] == '*':
                    pos[0] += 1
                    right = self.parse_factor()
                    left = ('BINOP', '*', left, right)
                return left

            def parse_factor(self):
                if pos[0] >= len(tokens):
                    raise ValueError("Unexpected end of expression")

                tok = tokens[pos[0]]
                if tok[0] == 'NUM':
                    pos[0] += 1
                    return tok[1]
                elif tok[0] == 'REF':
                    pos[0] += 1
                    return ('CELL', tok[1])
                elif tok[0] == 'OP' and tok[1] == '-':
                    pos[0] += 1
                    val = self.parse_factor()
                    return ('NEG', val)
                else:
                    raise ValueError(f"Unexpected token: {tok}")

        parser = Parser()
        result = parser.parse_expr()
        if pos[0] != len(tokens):
            raise ValueError("Unexpected tokens after expression")
        return result

    def _evaluate_cell(self, cell, visited=None):
        """Evaluate a cell's value, handling cycles by detecting them."""
        if visited is None:
            visited = set()

        if cell in visited:
            raise ValueError("Circular dependency detected")

