module.exports = function pLimit(n) {
  if (n < 1) throw new Error('n must be at least 1');

  let activeCount = 0;
  let queue = [];
  let isResolving = false;

  return async function(fn) {
    return new Promise((resolve, reject) => {
      const job = () => fn().then(resolve).catch(reject);

      if (activeCount < n) {
        activeCount++;
        job()
          .finally(() => {
            activeCount--;
            if (queue.length > 0 && !isResolving) {
              isResolving = true;
              const nextJob = queue.shift();
              isResolving = false;
              nextJob();
            }
          });
      } else {
        queue.push(job);
      }
    });
  };
};

