const jsonPointer = {
  get(doc, pointer) {
    if (pointer === '') return doc;
    if (!pointer.startsWith('/')) {
      throw new Error('Invalid JSON Pointer: must start with "/"');
    }

    const tokens = pointer.slice(1).split('/');
    let current = doc;

    for (const token of tokens) {
      // Decode escape sequences
      const decodedToken = token.replace(/~1/g, '/').replace(/~0/g, '~');

      if (current === null || typeof current !== 'object') {
        return undefined;
      }

      if (Array.isArray(current)) {
        const index = parseInt(decodedToken, 10);
        if (isNaN(index) || index < 0 || index >= current.length) {
          return undefined;
        }
        current = current[index];
      } else {
        if (!(decodedToken in current)) {
          return undefined;
        }
        current = current[decodedToken];
      }
    }

    return current;
  },

  set(doc, pointer, value) {
    if (pointer === '') {
      doc = value;
      return doc;
    }
    if (!pointer.startsWith('/')) {
      throw new Error('Invalid JSON Pointer: must start with "/"');
    }

    const tokens = pointer.slice(1).split('/');
    let current = doc;

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      // Decode escape sequences
      const decodedToken = token.replace(/~1/g, '/').replace(/~0/g, '~');

      if (i === tokens.length - 1) {
        // Last token: set the value
        if (Array.isArray(current)) {
          if (decodedToken === '-') {
            current.push(value);
          } else {
            const index = parseInt(decodedToken, 10);
            if (isNaN(index) || index < 0 || index > current.length) {
              current.push(value);
            } else {
              current[index] = value;
            }
          }
        } else {
          current[decodedToken] = value;
        }
        break;
      }

      // Ensure intermediate path exists
      if (current === null || typeof current !== 'object') {
        current = {};
      }

      if (Array.isArray(current)) {
        const index = parseInt(decodedToken, 10);
        if (isNaN(index) || index < 0 || index >= current.length) {
          current = [];
        } else {
          current = current[index];
        }
      } else {
        if (!(decodedToken in current)) {
          current = {};
        }
        current = current[decodedToken];
      }
    }

    return doc;
  }
};

