  const createProxy = (obj, path) => {
    return new Proxy(obj, {
      get(targetObj, prop, receiver) {
        if (prop === '__path') return path;
        const value = Reflect.get(targetObj, prop, receiver);
        if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
          return createProxy(value, [...path, String(prop)]);
        }
        return value;
      },
      set(targetObj, prop, newValue, receiver) {
        const currentPath = [...path, String(prop)];
        const oldValue = Reflect.get(targetObj, prop, receiver);

        // Handle nested object assignment
        if (typeof newValue === 'object' && newValue !== null && !Array.isArray(newValue)) {
          const nestedProxy = createProxy(newValue, currentPath);
          Object.defineProperty(targetObj, prop, {
            value: nestedProxy,
            writable: true,
            configurable: true,
            enumerable: true
          });
          newValue = nestedProxy;
        }

        // SameValueZero check
        if (Object.is(newValue, oldValue)) {
          return true;
        }

        const result = Reflect.set(targetObj, prop, newValue, receiver);
        if (result) {
          onChange(currentPath, newValue, oldValue);
        }
        return result;
      },
      deleteProperty(targetObj, prop) {
        const currentPath = [...path, String(prop)];
        const oldValue = Reflect.get(targetObj, prop, undefined);
        const result = Reflect.deleteProperty(targetObj, prop);
        if (result) {
          onChange(currentPath, undefined, oldValue);
        }
        return result;
      },
      ownKeys(targetObj) {
        return Reflect.ownKeys(targetObj);
      },
      has(targetObj, prop) {
        return Reflect.has(targetObj, prop);
      },
      getOwnPropertyDescriptor(targetObj, prop) {
        return Reflect.getOwnPropertyDescriptor(targetObj, prop);
      },
      isExtensible(targetObj) {
        return Reflect.isExtensible(targetObj);
      },
      preventExtensions(targetObj) {
        return Reflect.preventExtensions(targetObj);
      }
    });
  };

  return createProxy(target, []);
};

