    throw new Error('size must be a positive integer');
  }

  return async function* () {
    const buffer = [];
    let iterator;

    try {
      // Handle both sync and async iterables by attempting to get the iterator
      // If source is an async iterable, we need to await it.
      // However, standard async generators yield promises for values but the iterator itself is synchronous until next() is called.
      // To support true async iterables (where next() returns a promise), we detect this behavior.

      // We will assume `source` is either:
      // 1. A sync iterable (forSync)
      // 2. An async iterable (forAwait)

      // Attempt to get the iterator synchronously first.
      let iter;
      try {
        iter = source[Symbol.iterator]();
      } catch (e) {
        // Fallback for async iterables that don't have Symbol.iterator or throw on it
        // Actually, async iterables have Symbol.asyncIterator.
        if (!source[Symbol.asyncIterator]) {
          throw e;
        }
        iter = source[Symbol.asyncIterator]();
      }

      while (true) {
        // Check if consumer wants more data
        const hasMore = yield buffer.length > 0 ? undefined : null; 
