        // My logic: "While buffer length < size ... fetch".
        // This ensures we never fetch more than `size` items before yielding.
        // Even if the source is infinite, we stop fetching once we have `size` items, yield them, and wait for the next `next()` call.
        // This satisfies the laziness constraint.

        // What if the consumer stops AFTER receiving a full chunk?
        // Next time they call next(), we fetch another chunk.
        // If they stop calling next() entirely (break loop), the generator goes to finally, calls return(), and stops.
        // This seems correct.

        // One edge case: What if the source is an async iterable but we treat it as sync?
        // We must detect it.

        // Let's write the code.

        const isAsyncIterable = typeof source[Symbol.asyncIterator] === 'function';
        let iter;

        if (isAsyncIterable) {
            iter = source[Symbol.asyncIterator]();
        } else {
            iter = source[Symbol.iterator]();
        }

