                    result = await iter.next();
                } else {
                    result = iter.next();
                }

                if (result.done) {
                    break;
                }

                chunk.push(result.value);
            }

            if (chunk.length === 0) {
                // Source exhausted
                break;
            }

            yield chunk;
        }

        // Cleanup
        if (iter && !iter.return) {
            // Some iterators might not have return, though standard ones do.
            // Safe to ignore if missing.
        } else if (iter) {
            await iter.return?.();
        }
    } catch (err) {
        // Re-throw to propagate errors during consumption
        throw err;
    }
};
