module.exports = function memoize(fn, keyFn) {
  const calls = { count: 0 };
  let cacheMap;
  let cacheWeakMap;

  function getCache() {
    if (cacheMap === undefined) {
      cacheMap = new Map();
      cacheWeakMap = new WeakMap();
    }
    return { map: cacheMap, weakMap: cacheWeakMap };
  }

  function computeKey(arg) {
    if (keyFn !== undefined) {
      return keyFn(arg);
    }
    if (typeof arg === 'object' && arg !== null) {
      return arg; // Use object as key for WeakMap
    }
    return arg; // Primitive or non-object fallback to Map
  }

  function getCachedValue(key) {
    const { map, weakMap } = getCache();

    if (key instanceof Object) {
      if (weakMap.has(key)) {
        return weakMap.get(key);
      }
    } else {
      if (map.has(key)) {
        return map.get(key);
      }
    }
    return undefined;
  }

  function setCachedValue(key, value) {
    const { map, weakMap } = getCache();

    if (key instanceof Object) {
      weakMap.set(key, value);
    } else {
      map.set(key, value);
    }
  }

  function clearCache() {
    const { map, weakMap } = getCache();
    map.clear();
    weakMap.clear();
  }

  function wrapped(...args) {
    const arg = args[0];
    const key = computeKey(arg);

    const cached = getCachedValue(key);
    if (cached !== undefined) {
      return cached;
    }

    calls.count++;
    try {
      const result = fn.apply(this, args);
      setCachedValue(key, result);
      return result;
    } catch (e) {
      // Do not cache errors
      throw e;
    }
  }

  wrapped.cache = {
    calls: () => calls.count,
    clear: clearCache
  };

  return wrapped;
};

