module.exports = function createStore(reducer, initial) {
  let state = typeof initial === 'function' ? initial() : initial;
  let listeners = [];

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (typeof action !== 'object' || action === null) {
      throw new Error('Actions must be plain objects. While custom actions (strings, symbols, booleans, etc.) are supported by Redux, we only guarantee support for object actions (action must have a "type" property). In non-production environments, an error will be thrown.');
    }

    // Snapshot listeners before dispatching
    const currentListeners = [...listeners];

    try {
      state = reducer(state, action);
    } catch (e) {
      throw e;
    }

    // Notify all subscribers that were registered before this dispatch
    for (let i = 0; i < currentListeners.length; i++) {
      const listener = currentListeners[i];
      // Dispatching from inside a subscriber is allowed and processes to completion
      // before the outer notification continues. This is handled naturally by JS call stack.
      listener();
    }
  }

  function subscribe(fn) {
    if (typeof fn !== 'function') {
      throw new Error('Expected the observer to be a function');
    }

    // Prevent duplicate subscriptions
    if (listeners.indexOf(fn) !== -1) {
      return () => {};
    }

    listeners.push(fn);

    // Return unsubscribe function
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  return {
    getState,
    dispatch,
    subscribe
  };
};

