export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Set<(payload: E[keyof E]) => void>>()

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners.has(k)) {
      this.listeners.set(k, new Set())
    }
    this.listeners.get(k)!.add(fn)
    return () => {
      const set = this.listeners.get(k)
      if (set) {
        set.delete(fn)
        if (set.size === 0) this.listeners.delete(k)
      }
    }
  }

  emit<K extends keyof E>(k: K, payload?: E[K]): void {
    const type = E[k]
    // If the event type is void, we must not pass a second argument
    if (type === void) {
      const handlers = this.listeners.get(k)
      if (handlers) {
        handlers.forEach(fn => fn(payload as any))
      }
    } else {
      // For non-void types, payload is required and must match E[K]
      if (payload === undefined) {
        throw new Error(`Event "${String(k)}" requires a payload of type ${E[k].toString()}`)
      }
      const handlers = this.listeners.get(k)
      if (handlers) {
        handlers.forEach(fn => fn(payload))
      }
    }
  }
}

