export type Config = {
  name: string;
  age?: number;
};

type RequiredKeys<T> = {
  [K in keyof T]: undefined extends T[K] ? never : K;
}[keyof T];

type OptionalKeys<T> = {
  [K in keyof T]: undefined extends T[K] ? K : never;
}[keyof T];

type State<Config> = {
  data: Partial<Config>;
  requiredSet: Set<RequiredKeys<Config>>;
  optionalSet: Set<OptionalKeys<Config>>;
};

function createState<Config>() {
  const requiredKeys: RequiredKeys<Config>[] = Object.keys(
    {} as RequiredKeys<Config>
  ) as RequiredKeys<Config>[];
  const optionalKeys: OptionalKeys<Config>[] = Object.keys(
    {} as OptionalKeys<Config>
  ) as OptionalKeys<Config>[];

  return {
    data: {} as Partial<Config>,
    requiredSet: new Set(requiredKeys),
    optionalSet: new Set(optionalKeys),
  };
}

export function builder<Config>() {
  const state = createState<Config>();

  return {
    set(key: keyof Config, value: Config[keyof Config]) {
      if (state.requiredSet.has(key)) {
        state.data[key] = value;
        state.requiredSet.delete(key);
      } else if (state.optionalSet.has(key)) {
        state.data[key] = value;
        state.optionalSet.delete(key);
      } else {
        // This branch is unreachable due to TypeScript's type system
        // because 'key' must be either a required or optional key of Config.
        throw new Error(`Unknown key: ${key}`);
      }
      return this;
    },
    build() {
      if (state.requiredSet.size > 0) {
        // This error is enforced at compile time by the type system below
        throw new Error("Missing required keys");
      }
      return state.data as Config;
    },
  };
}

