export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends readonly any[]
    ? { [K in keyof T]: DeepAwaited<T[K]> }
    : T extends object
      ? { [K in keyof T]: DeepAwaited<T[K]> }
      : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved);
  }

  if (Array.isArray(value)) {
    return Promise.all(value.map(item => deepAwait(item)));
  }

  if (typeof value === 'object' && value !== null) {
    const entries = Object.entries(value);
    const awaitedEntries = await Promise.all(
      entries.map(([key, val]) => deepAwait(val).then(v => [key, v] as const))
    );
    return Object.fromEntries(awaitedEntries) as DeepAwaited<T>;
  }

  return value;
}

