  U extends any ? (k: () => U) => k : never
> extends (k: () => infer L) => void
  ? L
  : never;

export type UnionToTuple<U> = UnionToIntersection<
  U extends any ? { v: U } : never
> extends { v: infer F, rest: infer R }
  ? [...{ v: F }, ...UnionToTuple<R>]
  : U extends any
