export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RoutePath<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${string}` ? never : K;
}[keyof T];

export function defineRoutes<
  Routes extends Record<string, string>
>(routes: Routes): {
  [Name in keyof Routes]: (params: RouteParams<Routes[Name]>) => string;
} {
  const result: any = {};

  for (const [name, path] of Object.entries(routes)) {
    const paramNames = new Set<string>();
    const segments = path.split('/');

    for (const segment of segments) {
      if (segment.startsWith(':')) {
        paramNames.add(segment.slice(1));
      }
    }

    result[name as keyof Routes] = (params: any) => {
      // Compile-time check via TypeScript's strict mode and exact property types
      // will enforce that params has exactly the keys defined in paramNames.
      // If a key is missing or extra, TS will error before runtime.

      let interpolated = path;
      for (const paramName of paramNames) {
        const regex = new RegExp(`:\\${paramName}`, 'g');
        interpolated = interpolated.replace(regex, String(params[paramName]));
      }
      return interpolated;
    };
  }

  return result as any;
}

